import sys

def merge_sort(fractions):
    if len(fractions) <= 1:
        return fractions
    mid = len(fractions) // 2
    left = merge_sort(fractions[:mid])
    right = merge_sort(fractions[mid:])
    return merge(left, right)

def merge(left, right):
    result = []
    i = j = 0
    while i < len(left) and j < len(right):
        if compare_fractions(left[i], right[j]) <= 0:
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
    result.extend(left[i:])
    result.extend(right[j:])
    return result

def compare_fractions(a, b):
    return a[0] * b[1] - b[0] * a[1]

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    fractions = []
    index = 1
    for i in range(n):
        num = int(data[index])
        den = int(data[index + 1])
        fractions.append((num, den))
        index += 2
    sorted_fractions = merge_sort(fractions)
    for num, den in sorted_fractions:
        print(f"{num}/{den}")

if __name__ == "__main__":
    main()
